#!/usr/bin/env bash
# R10 "iq" lane art: Records / Record Run / Cat IQ / rank icons. ONE at a time via studio/bin/art.sh. Processed by proc_iq.py.
cd "$(dirname "$0")"
S="Art style (must match across the whole set): soft painterly 3D cartoon like a polished 2026 mobile game, smooth chunky rounded felt-toy shapes, clean soft shading and gentle gradients, NOT photorealistic, NOT flat vector, no outlines. Palette: sage green walls #689A8D, honey oak wood #BF7948 with darker oak #8E5530, ivory #FFF0D3, rust red #BD582F, warm cream #fff6e5. One warm sunlight from the upper right, soft shadows falling down-left. Absolutely no text, no letters, no numbers, no logo, no watermark."
K="Place every item on a flat solid pure magenta #ff00ff background with nothing else on it so it can be keyed out; no shadow on the background, items must not touch each other or the image edge."
G="Arrange as a clean grid with wide magenta gaps between items, each item fully visible and the same scale."
g(){ n=$1; shift; if [ -s "$n.png" ] && [ -z "$FORCE" ]; then echo "skip $n"; return; fi; echo "gen $n $(date +%T)"; timeout 600 /c/Users/Admin/Documents/Msjelly/studio/bin/art.sh "$(pwd -W)/$n.png" "$*" >/dev/null 2>&1; ls -la "$n.png" 2>&1 | awk '{print $5}'; }
g iq_icons "Six chunky game UI icons for a cozy cat puzzle game, straight front view, each a single object: (1) a round brass stopwatch with two small cat ears on top and a honey-oak crown button, ivory face with two simple hands, no numbers; (2) a gold medal shaped like a stopwatch face with cat ears, hanging from a short rust red ribbon; (3) the same stopwatch medal in shiny silver with a sage green ribbon; (4) the same stopwatch medal in warm bronze copper with a cream ribbon; (5) a cute orange tabby cat head wearing big round glasses and a tiny graduation cap, smiling clever expression; (6) a three-step wooden winners podium in honey oak with a small paw print on the top step. Arrange as 2 rows x 3 columns. $K $G $S"
